import React, { useEffect, useRef, useState } from "react";
import { socket } from "../socket";

const STATUS_COLORS = {
  thinking: "text-terminal-amber",
  done: "text-terminal-green",
  error: "text-terminal-red",
};

export default function LogStream({ jobId }) {
  const [lines, setLines] = useState([]);
  const [result, setResult] = useState(null);
  const bottomRef = useRef(null);

  useEffect(() => {
    if (!jobId) return;

    socket.emit("join_job", jobId);

    function appendLine(text, colorClass) {
      setLines((prev) => [...prev, { text, colorClass, key: prev.length }]);
    }

    function onAgentStatus(data) {
      const color = STATUS_COLORS[data.status] || "text-terminal-text";
      appendLine(`[${data.agent}] ${data.status}${data.next ? ` -> ${data.next}` : ""}`, color);
    }

    function onAgentLog(data) {
      appendLine(`[${data.agent}] ${data.message}`, "text-terminal-text");
    }

    function onJobComplete(data) {
      appendLine("Job complete.", "text-terminal-green");
      setResult(data);
    }

    function onJobError(data) {
      appendLine(`Job failed: ${data.message}`, "text-terminal-red");
    }

    socket.on("agent_status", onAgentStatus);
    socket.on("agent_log", onAgentLog);
    socket.on("job_complete", onJobComplete);
    socket.on("job_error", onJobError);

    return () => {
      socket.off("agent_status", onAgentStatus);
      socket.off("agent_log", onAgentLog);
      socket.off("job_complete", onJobComplete);
      socket.off("job_error", onJobError);
    };
  }, [jobId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [lines]);

  return (
    <div className="w-full max-w-2xl mx-auto mt-6 font-mono">
      <div className="bg-black border border-terminal-border rounded-lg p-4 h-72 overflow-y-auto">
        {lines.length === 0 && (
          <p className="text-terminal-border text-sm">Waiting for agent activity...</p>
        )}
        {lines.map((line) => (
          <p key={line.key} className={`text-sm ${line.colorClass}`}>
            {line.text}
          </p>
        ))}
        <div ref={bottomRef} />
      </div>

      {result && (
        <div className="mt-4 bg-terminal-bg border border-terminal-border rounded-lg p-4 text-terminal-text text-sm">
          <p>Files scanned: {result.files?.length ?? 0}</p>
          <p>Dependencies found: {Object.keys(result.dependencies || {}).length}</p>
          <p>Vulnerabilities: {result.vulnerabilities?.length ?? 0}</p>
          {result.vulnerabilities?.length > 0 && (
            <ul className="list-disc list-inside text-terminal-amber mt-1">
              {result.vulnerabilities.map((v, i) => (
                <li key={i}>{v}</li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}
